@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');

:root {
  --bg: #02070c;
  --bg-deep: #01050a;
  --panel: rgba(7, 21, 28, 0.86);
  --panel-solid: #07151c;
  --panel-raised: rgba(11, 31, 40, 0.92);
  --line: rgba(97, 219, 222, 0.14);
  --line-strong: rgba(97, 240, 246, 0.32);
  --text: #e6fbfb;
  --muted: #7899a1;
  --muted-2: #4e6c74;
  --cyan: #54f3ff;
  --cyan-soft: #35b8c7;
  --mint: #65ffad;
  --amber: #ffc35f;
  --rose: #ff6f9b;
  --violet: #b994ff;
  --danger: #ff5b6e;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.5);
  --mono: 'JetBrains Mono', 'SFMono-Regular', Consolas, monospace;
  --sans: 'Space Grotesk', 'Trebuchet MS', system-ui, sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  min-height: 100%;
  background: var(--bg-deep);
}

body {
  margin: 0;
  min-height: 100vh;
  color: var(--text);
  font-family: var(--sans);
  background:
    radial-gradient(ellipse 65% 55% at 12% -5%, rgba(32, 87, 139, 0.28), transparent 72%),
    radial-gradient(ellipse 58% 45% at 92% 104%, rgba(0, 180, 158, 0.14), transparent 74%),
    radial-gradient(ellipse 40% 35% at 55% 55%, rgba(16, 52, 66, 0.15), transparent 70%),
    var(--bg);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

button {
  font: inherit;
  color: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: rgba(84, 243, 255, 0.22);
  color: white;
}

.ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}

.ambient-grid {
  position: absolute;
  inset: -20%;
  background-image:
    linear-gradient(rgba(91, 197, 204, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(91, 197, 204, 0.035) 1px, transparent 1px);
  background-size: 58px 58px;
  mask-image: radial-gradient(ellipse 65% 65% at 50% 40%, black, transparent 78%);
  transform: perspective(800px) rotateX(12deg) scale(1.1);
}

.orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(20px);
  opacity: 0.55;
  animation: orb-float 18s ease-in-out infinite alternate;
}

.orb-a {
  width: 460px;
  height: 460px;
  left: -190px;
  top: 16%;
  background: radial-gradient(circle, rgba(14, 133, 170, 0.16), transparent 68%);
}

.orb-b {
  width: 560px;
  height: 560px;
  right: -230px;
  top: 30%;
  background: radial-gradient(circle, rgba(36, 211, 178, 0.09), transparent 70%);
  animation-delay: -9s;
}

.orb-c {
  width: 500px;
  height: 500px;
  left: 37%;
  bottom: -300px;
  background: radial-gradient(circle, rgba(134, 84, 255, 0.08), transparent 70%);
  animation-delay: -3s;
}

@keyframes orb-float {
