.level-brief {
  margin: 0;
  color: #8eacb1;
  font-size: 12.5px;
  line-height: 1.65;
}

.objective-block {
  margin-top: clamp(23px, 3.4vh, 34px);
}

.section-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

.live-tag {
  position: relative;
  padding-left: 10px;
  color: rgba(101, 255, 173, 0.7);
  font-size: 7.5px;
  letter-spacing: 0.12em;
}

.live-tag::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  width: 4px;
  height: 4px;
  margin-top: -2px;
  border-radius: 50%;
  background: var(--mint);
  box-shadow: 0 0 7px rgba(101, 255, 173, 0.85);
  animation: blink 2s ease-in-out infinite;
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

.objective-list {
  display: flex;
  flex-direction: column;
  gap: 11px;
  margin: 14px 0 0;
  padding: 0;
  list-style: none;
}

.objective-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  color: #98b6ba;
  font-size: 11.5px;
  line-height: 1.35;
  transition: color 0.25s ease;
}

.objective-list li .objective-dot {
  display: grid;
  place-items: center;
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
  margin-top: 0;
  border: 1px solid rgba(135, 206, 211, 0.18);
  border-radius: 50%;
  color: transparent;
  font-size: 8px;
  transition: all 0.25s ease;
}

.objective-list li.done {
  color: #d9f8ee;
}

.objective-list li.done .objective-dot {
  border-color: rgba(101, 255, 173, 0.45);
  color: #02130f;
  background: var(--mint);
  box-shadow: 0 0 12px rgba(101, 255, 173, 0.35);
}

.objective-list li.failed {
  color: #ffc8c8;
}

.objective-list li.failed .objective-dot {
  border-color: rgba(255, 91, 110, 0.5);
  color: #ffd6d6;
  background: rgba(255, 91, 110, 0.2);
}

.engineer-note {
  display: flex;
  gap: 10px;
  margin-top: auto;
  margin-bottom: 17px;
  padding: 13px 12px;
  border: 1px solid rgba(255, 195, 95, 0.14);
  border-radius: 11px;
  background:
    linear-gradient(120deg, rgba(255, 195, 95, 0.055), transparent 70%),
    rgba(255, 195, 95, 0.018);
}

.note-icon {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  color: rgba(255, 195, 95, 0.82);
}

.note-icon svg {
  width: 100%;
  height: 100%;
}

.engineer-note span {
  display: block;
  margin-bottom: 4px;
  color: rgba(255, 195, 95, 0.7);
  font-family: var(--mono);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.15em;
}

.engineer-note p {
  margin: 0;
  color: #a9977d;
  font-size: 10.5px;
  line-height: 1.55;
}

.mission-footer {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 12px;
  border-top: 1px solid rgba(97, 219, 222, 0.09);
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.09em;
}

.mission-footer b {
  color: var(--muted);
  font-weight: 600;
}

.signal-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, rgba(97, 219, 222, 0.14), transparent);
}

/* ------------------------------------ board ------------------------------------ */

.board-column {
  min-width: 0;
  animation: panel-in 0.65s 0.04s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.board-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 35px;
  margin-bottom: 8px;
  padding: 0 3px;
}

.board-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--muted-2);
  box-shadow: 0 0 0 4px rgba(120, 153, 161, 0.07);
  transition: all 0.3s ease;
}

.board-status-pill.live .status-dot {
  background: var(--cyan);
  box-shadow: 0 0 0 4px rgba(84, 243, 255, 0.08), 0 0 10px rgba(84, 243, 255, 0.7);
  animation: blink 2.2s ease-in-out infinite;
}

.board-status-pill.solved .status-dot {
  background: var(--mint);
  box-shadow: 0 0 0 4px rgba(101, 255, 173, 0.1), 0 0 14px rgba(101, 255, 173, 0.9);
  animation: none;
}

.board-status-pill.danger .status-dot {
  background: var(--danger);
  box-shadow: 0 0 0 4px rgba(255, 91, 110, 0.1), 0 0 12px rgba(255, 91, 110, 0.8);
  animation: blink 0.65s ease-in-out infinite;
}

.board-status-pill.warning .status-dot {
  background: var(--amber);
  box-shadow: 0 0 0 4px rgba(255, 195, 95, 0.08), 0 0 12px rgba(255, 195, 95, 0.6);
}

.board-top-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.interaction-hint {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.interaction-hint svg {
  width: 14px;
  height: 14px;
}

.board-icon-button {
  width: 31px;
  height: 31px;
  border-radius: 8px;
}

.board-icon-button svg {
  width: 16px;
  height: 16px;
}

.board-icon-button.active {
  color: var(--amber);
  border-color: rgba(255, 195, 95, 0.5);
  background: rgba(255, 195, 95, 0.08);
  box-shadow: 0 0 16px rgba(255, 195, 95, 0.12);
}

.board-shell {
  position: relative;
  padding: 13px;
  border: 1px solid rgba(102, 218, 224, 0.22);
  border-radius: 24px;
  background:
    linear-gradient(145deg, #12303a 0%, #071820 22%, #06131a 55%, #0a222c 100%);
  box-shadow:
    0 30px 80px rgba(0, 0, 0, 0.45),
    0 0 0 1px rgba(0, 0, 0, 0.6),
    inset 0 1px 0 rgba(198, 255, 255, 0.13),
    inset 0 -1px 0 rgba(0, 0, 0, 0.55);
}

.board-shell::before {
  content: '';
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(84, 243, 255, 0.05);
  border-radius: 18px;
  pointer-events: none;
}

.board-shell::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(120deg, rgba(84, 243, 255, 0.07), transparent 26%, transparent 72%, rgba(101, 255, 173, 0.035));
  pointer-events: none;
}

.board-screw {
  position: absolute;
  z-index: 3;
  width: 10px;
  height: 10px;
  border: 1px solid rgba(173, 237, 238, 0.22);
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #3b5860, #0a1c22 65%);
  box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.15);
}

.board-screw::after {
  content: '';
  position: absolute;
  left: 2px;
  right: 2px;
  top: 4px;
  height: 1px;
  background: rgba(2, 9, 12, 0.8);
  transform: rotate(-25deg);
}

.screw-tl { left: 6px; top: 6px; }
.screw-tr { right: 6px; top: 6px; }
.screw-bl { left: 6px; bottom: 6px; }
.screw-br { right: 6px; bottom: 6px; }

.canvas-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1040 / 650;
  border-radius: 16px;
  overflow: hidden;
  background: #041018;
  cursor: crosshair;
  touch-action: none;
  isolation: isolate;
}

.canvas-wrap.cut-mode {
  cursor: cell;
}

.canvas-wrap.dragging {
  cursor: grabbing;
}

#boardCanvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  outline: none;
}

.board-hud {
  position: absolute;
  top: 12px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 2px;
  pointer-events: none;
  padding: 7px 9px;
  border: 1px solid rgba(97, 219, 222, 0.08);
  border-radius: 6px;
  background: rgba(2, 10, 14, 0.42);
  backdrop-filter: blur(4px);
}

.hud-left { left: 14px; }
.hud-right { right: 14px; align-items: flex-end; }

.hud-label {
  color: rgba(83, 143, 150, 0.75);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.17em;
}

.board-hud strong {
  display: flex;
  align-items: center;
  gap: 5px;
  color: rgba(198, 239, 240, 0.78);
  font-family: var(--mono);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.06em;
}

.hud-led {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--muted-2);
  box-shadow: 0 0 0 2px rgba(120, 153, 161, 0.06);
  transition: all 0.3s ease;
}

.hud-led.on {
  background: var(--mint);
  box-shadow: 0 0 8px rgba(101, 255, 173, 0.9);
}

.hint-banner {
  position: absolute;
  left: 50%;
  bottom: 14px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: min(88%, 490px);
  padding: 8px 13px;
  border: 1px solid rgba(255, 195, 95, 0.22);
  border-radius: 99px;
  background: rgba(7, 20, 25, 0.91);
  color: #e9cf9f;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.35), 0 0 18px rgba(255, 195, 95, 0.05);
  transform: translate(-50%, 12px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease, transform 0.22s ease;
}

.hint-banner.visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.hint-spark {
  width: 6px;
  height: 6px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 9px rgba(255, 195, 95, 0.9);
  animation: blink 1.4s ease-in-out infinite;
}

.board-caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 13px 10px 12px;
}

.caption-status {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.caption-icon {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  border: 1px solid rgba(84, 243, 255, 0.15);
  border-radius: 8px;
  background: rgba(84, 243, 255, 0.035);
  color: var(--cyan-soft);
}

.caption-icon::before {
  content: '';
  width: 8px;
  height: 8px;
  border: 1px solid currentColor;
  border-radius: 50%;
  box-shadow: 0 0 8px currentColor;
}

.caption-icon.ok {
  color: var(--mint);
  border-color: rgba(101, 255, 173, 0.25);
  background: rgba(101, 255, 173, 0.055);
}

.caption-icon.bad {
  color: var(--danger);
  border-color: rgba(255, 91, 110, 0.26);
  background: rgba(255, 91, 110, 0.06);
}

.caption-icon.warn {
  color: var(--amber);
  border-color: rgba(255, 195, 95, 0.25);
  background: rgba(255, 195, 95, 0.055);
}

.caption-status b {
  display: block;
  margin-bottom: 3px;
  color: #c6e3e4;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.12em;
}

.caption-status small {
  display: block;
  color: var(--muted-2);
  font-size: 9px;
  line-height: 1.45;
}

.caption-stats {
  display: flex;
  gap: 18px;
  flex: 0 0 auto;
}

.caption-stats span {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
}

.caption-stats small {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.11em;
}

.caption-stats b {
  color: #acd1d3;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
}

.tool-row {
  display: grid;
  grid-template-columns: 1.35fr 1fr 1fr 1fr;
  gap: 8px;
}

.tool {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 45px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(8, 24, 31, 0.78);
  color: #8eacb1;
  font-size: 10px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.18s ease;
}

.tool svg {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
}

.tool kbd {
  margin-left: auto;
  padding: 2px 4px;
  border: 1px solid rgba(133, 196, 200, 0.13);
  border-radius: 4px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
}

.tool:hover {
  color: #d5eeee;
  border-color: var(--line-strong);
  background: rgba(12, 37, 46, 0.9);
}

.tool:active {
  transform: translateY(1px);
}

.tool-primary {
  color: #05201c;
  border-color: rgba(101, 255, 173, 0.5);
  background: linear-gradient(135deg, #a8ffcf, #61f4ad 45%, #30d9a0);
  box-shadow: 0 7px 26px rgba(57, 231, 165, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.4);
  font-weight: 600;
}

.tool-primary:hover {
  color: #021a15;
  border-color: rgba(170, 255, 213, 0.8);
  background: linear-gradient(135deg, #c1ffde, #71ffba 45%, #3de7ae);
  box-shadow: 0 9px 32px rgba(57, 231, 165, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

.tool-primary kbd {
  color: rgba(1, 34, 25, 0.55);
  border-color: rgba(1, 34, 25, 0.16);
}

.tool.active {
  color: var(--amber);
  border-color: rgba(255, 195, 95, 0.45);
  background: rgba(255, 195, 95, 0.075);
}

/* ------------------------------------ right panel ------------------------------------ */

.control-panel {
  padding: 15px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 560px;
  animation: panel-in 0.65s 0.08s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.score-card {
  padding: 15px 14px 13px;
  border: 1px solid rgba(84, 243, 255, 0.13);
  border-radius: 13px;
  background:
    radial-gradient(circle at 90% 0%, rgba(84, 243, 255, 0.09), transparent 58%),
    rgba(4, 15, 20, 0.58);
}

.score-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.score-delta {
  padding: 3px 5px;
  border: 1px solid rgba(101, 255, 173, 0.2);
  border-radius: 4px;
  color: var(--mint);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.11em;
}

.score-delta.penalty {
  color: var(--amber);
  border-color: rgba(255, 195, 95, 0.25);
}

.score-number {
  margin: 7px 0 2px;
  color: white;
  font-family: var(--mono);
  font-size: clamp(27px, 2.5vw, 36px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.05em;
  text-shadow: 0 0 30px rgba(84, 243, 255, 0.22);
  font-variant-numeric: tabular-nums;
}

.star-row {
  display: flex;
  gap: 3px;
  margin: 9px 0 11px;
  font-size: 13px;
  color: rgba(129, 173, 178, 0.17);
  letter-spacing: 1px;
}

.star-row .star.on {
  color: var(--amber);
  text-shadow: 0 0 12px rgba(255, 195, 95, 0.55);
}

.score-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.1em;
}

.score-meta b {
  color: var(--muted);
  font-weight: 500;
}

.score-meter {
  height: 2px;
  margin-top: 9px;
  border-radius: 99px;
  background: rgba(146, 220, 225, 0.08);
  overflow: hidden;
}

.score-meter span {
  display: block;
  width: 50%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--cyan-soft), var(--mint));
  box-shadow: 0 0 10px rgba(84, 243, 255, 0.35);
  transition: width 0.4s ease, background 0.3s ease;
}

.diagnostic-card,
.legend-card {
  padding: 13px 13px 11px;
  border: 1px solid rgba(97, 219, 222, 0.09);
  border-radius: 12px;
  background: rgba(4, 14, 19, 0.4);
}

.diagnostic-card .section-label {
  margin-bottom: 9px;
}

.diagnostic-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 25px;
  border-top: 1px solid rgba(97, 219, 222, 0.055);
  color: #78999f;
  font-size: 9px;
}

.diagnostic-row:first-of-type {
  border-top: 0;
}

.diagnostic-row b {
  margin-left: auto;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 7.5px;
  font-weight: 500;
  letter-spacing: 0.03em;
  text-align: right;
}

.diagnostic-row b.ok {
  color: var(--mint);
}

.diagnostic-row b.bad {
  color: var(--danger);
}

.diagnostic-row b.warn {
  color: var(--amber);
}

.diag-icon {
  position: relative;
  width: 11px;
  height: 11px;
  flex: 0 0 auto;
  opacity: 0.66;
}

.diag-icon.power {
  border: 1px solid currentColor;
  border-radius: 2px;
}

.diag-icon.power::after {
  content: '';
  position: absolute;
  left: 2px;
  right: 2px;
  top: 4px;
  height: 1px;
  background: currentColor;
}

.diag-icon.load {
  border: 1px solid currentColor;
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px rgba(3, 12, 16, 0.8);
}

.diag-icon.logic {
  border-left: 1px solid currentColor;
  border-radius: 0 5px 5px 0;
  background: currentColor;
  clip-path: polygon(0 0, 0 100%, 100% 50%);
  opacity: 0.3;
}

.diag-icon.safety {
  border: 1px solid currentColor;
  border-radius: 2px;
  transform: rotate(45deg) scale(0.75);
}

.legend-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px 8px;
  margin-top: 11px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #6f9097;
  font-size: 8.5px;
}

.legend-glyph {
  display: grid;
  place-items: center;
  width: 19px;
  height: 19px;
  flex: 0 0 auto;
  border: 1px solid rgba(97, 219, 222, 0.13);
  border-radius: 4px;
  background: rgba(4, 15, 20, 0.52);
  color: var(--cyan-soft);
}

.battery-glyph {
  font-family: var(--mono);
  font-size: 6px;
  font-weight: 600;
}

.switch-glyph i {
  display: block;
  width: 9px;
  height: 1px;
  background: currentColor;
  transform: rotate(-28deg);
  box-shadow: 0 0 5px currentColor;
}

.led-glyph::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 7px rgba(255, 195, 95, 0.8);
}

.gate-glyph {
  font-family: var(--mono);
  font-size: 7px;
}

.port-glyph::before {
  content: '';
  width: 6px;
  height: 6px;
  border: 1px solid currentColor;
  border-radius: 50%;
  box-shadow: 0 0 0 2px rgba(84, 243, 255, 0.08);
}

.wire-glyph::before {
  content: '';
  width: 11px;
  height: 1px;
  background: currentColor;
  box-shadow: 0 0 6px currentColor;
}

.next-chip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  margin-top: auto;
  padding: 11px 12px;
  border: 1px solid rgba(84, 243, 255, 0.12);
  border-radius: 11px;
  background: linear-gradient(110deg, rgba(84, 243, 255, 0.045), rgba(101, 255, 173, 0.02));
  cursor: pointer;
  text-align: left;
  transition: all 0.18s ease;
}

.next-chip:hover {
  border-color: rgba(84, 243, 255, 0.3);
  background: linear-gradient(110deg, rgba(84, 243, 255, 0.08), rgba(101, 255, 173, 0.035));
}

.next-chip small {
  display: block;
  margin-bottom: 3px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.13em;
}

.next-chip b {
  color: #a8cdcf;
  font-size: 10px;
  font-weight: 500;
}

.next-chip svg {
  width: 17px;
  height: 17px;
  color: var(--cyan-soft);
  flex: 0 0 auto;
}

.app-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 11px 3px 0;
  border-top: 1px solid rgba(97, 219, 222, 0.08);
  color: #3e5b62;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.1em;
}

.app-footer span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.app-footer i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--cyan-soft);
  box-shadow: 0 0 6px rgba(84, 243, 255, 0.5);
}

/* ------------------------------------ modals ------------------------------------ */

.modal {
  width: min(1040px, calc(100vw - 28px));
  max-height: min(90vh, 900px);
  padding: 0;
  border: 1px solid rgba(97, 228, 234, 0.22);
  border-radius: 22px;
  color: var(--text);
  background: #06151c;
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.72), 0 0 0 1px rgba(0, 0, 0, 0.5);
  overflow: hidden;
}

.modal::backdrop {
  background: rgba(0, 7, 11, 0.76);
  backdrop-filter: blur(8px);
}

.modal[open] {
  animation: modal-in 0.28s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes modal-in {
  from { opacity: 0; transform: translateY(14px) scale(0.985); }
}

.modal-shell {
  max-height: min(90vh, 900px);
  overflow: auto;
  background:
    radial-gradient(ellipse 70% 55% at 15% 0%, rgba(21, 100, 125, 0.18), transparent 70%),
    linear-gradient(150deg, #071921, #051218 60%, #040d12);
}

.modal-header {
  position: sticky;
  top: 0;
  z-index: 3;
  display: flex;
  align-items: flex-start;
  gap: 22px;
  padding: 27px 30px 22px;
  border-bottom: 1px solid rgba(97, 219, 222, 0.1);
  background: rgba(5, 17, 23, 0.91);
  backdrop-filter: blur(12px);
}

.modal-header > div:first-child {
  flex: 1;
}

.modal-header h2 {
  margin: 9px 0 5px;
  font-size: clamp(26px, 3vw, 38px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.04em;
}

.modal-header p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.modal-progress {
  display: flex;
  align-items: center;
  gap: 13px;
  padding-top: 6px;
}

.modal-progress-ring {
  --progress: 0;
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background:
    radial-gradient(circle at center, #06151c 58%, transparent 59%),
    conic-gradient(var(--cyan) calc(var(--progress) * 1%), rgba(84, 243, 255, 0.09) 0);
  box-shadow: 0 0 25px rgba(84, 243, 255, 0.1);
}

.modal-progress-ring span {
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
}

.modal-progress b {
  display: block;
  color: #c3e0e2;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
}

.modal-progress small {
  display: block;
  margin-top: 3px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.12em;
}

.modal-close {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  padding: 0 0 3px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(5, 17, 23, 0.7);
  color: var(--muted);
  font-family: var(--sans);
  font-size: 25px;
  font-weight: 300;
  line-height: 1;
  cursor: pointer;
  transition: all 0.18s ease;
}

.modal-close:hover {
  color: white;
  border-color: var(--line-strong);
}

.modal-body {
  padding: 24px 30px 28px;
}

.modal-footer {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 14px 30px;
  border-top: 1px solid rgba(97, 219, 222, 0.1);
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
}

.modal-footer span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.legend-dot.complete { background: var(--mint); }
.legend-dot.current { background: var(--cyan); }
.legend-dot.locked { background: var(--muted-2); }

.text-button {
  padding: 3px 0;
  border: 0;
  background: transparent;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.05em;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.text-button:hover {
  color: var(--rose);
}

#resetProgressButton {
  margin-left: auto;
}

.chapter-section {
  margin-bottom: 27px;
}

.chapter-section:last-child {
  margin-bottom: 0;
}

.chapter-heading {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 11px;
}

.chapter-heading h3 {
  margin: 0;
  color: #c9e5e5;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.01em;
}

.chapter-heading span {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
}

.chapter-heading i {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, rgba(97, 219, 222, 0.12), transparent);
}

.level-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.level-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 100px;
  padding: 11px;
  border: 1px solid rgba(97, 219, 222, 0.1);
  border-radius: 10px;
  background: rgba(5, 18, 24, 0.58);
  color: var(--text);
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  transition: all 0.18s ease;
}

.level-card::after {
  content: '';
  position: absolute;
  inset: auto 0 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(84, 243, 255, 0.25), transparent);
  opacity: 0;
  transition: opacity 0.18s ease;
}

.level-card:hover:not(.locked) {
  border-color: rgba(84, 243, 255, 0.32);
  background: rgba(9, 31, 40, 0.8);
  transform: translateY(-2px);
}

.level-card:hover:not(.locked)::after {
  opacity: 1;
}

.level-card.completed {
  border-color: rgba(101, 255, 173, 0.18);
  background: linear-gradient(140deg, rgba(101, 255, 173, 0.055), rgba(5, 18, 24, 0.58) 60%);
}

.level-card.current {
  border-color: rgba(84, 243, 255, 0.45);
  background: linear-gradient(140deg, rgba(84, 243, 255, 0.09), rgba(5, 18, 24, 0.6) 65%);
  box-shadow: inset 0 0 20px rgba(84, 243, 255, 0.03);
}

.level-card.locked {
  cursor: not-allowed;
  opacity: 0.48;
}

.level-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 9px;
}

.level-card-number {
  color: var(--cyan-soft);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.level-card.completed .level-card-number {
  color: var(--mint);
}

.level-card-lock {
  width: 10px;
  height: 10px;
  color: var(--muted-2);
}

.level-card h4 {
  margin: 0 0 7px;
  color: #c8e2e3;
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1.2;
}

.level-card.completed h4 {
  color: #e2fff4;
}

.level-card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
  margin-top: auto;
  padding-top: 6px;
}

.difficulty-dots {
  display: flex;
  gap: 2px;
}

.difficulty-dots i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(123, 174, 179, 0.2);
}

.difficulty-dots i.on {
  background: var(--amber);
}

.mini-stars {
  color: rgba(123, 174, 179, 0.18);
  font-size: 7px;
  letter-spacing: 0.3px;
}

.mini-stars .on {
  color: var(--amber);
}

.level-card .card-node {
  position: absolute;
  right: -9px;
  bottom: -9px;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(84, 243, 255, 0.08);
  border-radius: 50%;
}

.level-card .card-node::after {
  content: '';
  position: absolute;
  inset: 9px;
  border-radius: 50%;
  background: rgba(84, 243, 255, 0.08);
}

.level-card.completed .card-node {
  border-color: rgba(101, 255, 173, 0.12);
}

.level-card.completed .card-node::after {
  background: rgba(101, 255, 173, 0.12);
}

/* completion */

.complete-modal {
  width: min(500px, calc(100vw - 28px));
  overflow: visible;
}

.completion-shell {
  position: relative;
  padding: 35px 34px 26px;
  background:
    radial-gradient(circle at 50% 2%, rgba(84, 243, 255, 0.14), transparent 46%),
    radial-gradient(circle at 50% 40%, rgba(101, 255, 173, 0.05), transparent 60%),
    linear-gradient(160deg, #071c24, #041117 70%);
  overflow: hidden;
}

.completion-burst {
  position: absolute;
  top: -50px;
  left: 50%;
  width: 300px;
  height: 300px;
  transform: translateX(-50%);
  pointer-events: none;
}

.completion-burst span {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(84, 243, 255, 0.11);
  border-radius: 50%;
  animation: burst 4s ease-out infinite;
}

.completion-burst span:nth-child(2) { animation-delay: 1s; }
.completion-burst span:nth-child(3) { animation-delay: 2s; }
.completion-burst span:nth-child(4) { animation-delay: 3s; }

@keyframes burst {
  0% { transform: scale(0.35); opacity: 0; }
  20% { opacity: 0.75; }
  100% { transform: scale(1.35); opacity: 0; }
}

.completion-badge {
  position: relative;
  z-index: 1;
  width: 74px;
  height: 74px;
  margin: 0 auto 18px;
  color: var(--mint);
  filter: drop-shadow(0 0 20px rgba(101, 255, 173, 0.35));
}

.completion-shell > .eyebrow {
  display: block;
  position: relative;
  z-index: 1;
  text-align: center;
}

.completion-shell h2 {
  position: relative;
  z-index: 1;
  margin: 9px 0 10px;
  text-align: center;
  font-size: clamp(36px, 7vw, 48px);
  font-weight: 300;
  line-height: 0.9;
  letter-spacing: -0.045em;
}

.completion-shell h2 b {
  color: var(--cyan);
  font-weight: 600;
  text-shadow: 0 0 35px rgba(84, 243, 255, 0.3);
}

.completion-shell > p {
  position: relative;
  z-index: 1;
  margin: 0 auto 17px;
  max-width: 310px;
  color: var(--muted);
  text-align: center;
  font-size: 11.5px;
  line-height: 1.55;
}

.completion-stars {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: center;
  gap: 8px;
  margin: 18px 0;
  color: rgba(134, 176, 180, 0.15);
  font-size: 30px;
}

.completion-stars span {
  display: inline-block;
  transform: scale(0.65);
  opacity: 0;
  transition: all 0.35s cubic-bezier(0.2, 1.5, 0.4, 1);
}

.completion-stars span.on {
  color: var(--amber);
  text-shadow: 0 0 22px rgba(255, 195, 95, 0.7);
  transform: scale(1);
  opacity: 1;
}

.completion-stars span.on:nth-child(2) { transition-delay: 0.08s; }
.completion-stars span.on:nth-child(3) { transition-delay: 0.16s; }

.completion-score {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  margin: 0 auto 16px;
  padding: 14px;
  border: 1px solid rgba(84, 243, 255, 0.13);
  border-radius: 12px;
  background: rgba(4, 15, 20, 0.45);
}

.completion-score small {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.16em;
}

.completion-score strong {
  margin: 4px 0 2px;
  color: white;
  font-family: var(--mono);
  font-size: 38px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.04em;
  text-shadow: 0 0 24px rgba(84, 243, 255, 0.18);
}

.completion-score span {
  color: var(--mint);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.13em;
}

.completion-note {
  position: relative;
  z-index: 1;
  min-height: 16px;
  margin-bottom: 15px;
  color: var(--muted-2);
  text-align: center;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
}

.completion-actions {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.45fr 1fr;
  gap: 8px;
}

.button-primary {
  color: #03201a;
  border-color: rgba(101, 255, 173, 0.45);
  background: linear-gradient(135deg, #b5ffd7, #6bffb5 45%, #37e1a7);
  box-shadow: 0 7px 26px rgba(57, 231, 165, 0.13);
  font-weight: 600;
}

.button-primary:hover {
  background: linear-gradient(135deg, #d0ffe6, #7dffc2 45%, #48f1b7);
  box-shadow: 0 9px 32px rgba(57, 231, 165, 0.22);
}

.button-primary span {
  margin-left: auto;
  font-size: 16px;
  line-height: 0;
}

.map-link {
  display: block;
  margin: 16px auto 0;
  position: relative;
  z-index: 1;
}

/* help */

.help-modal {
  width: min(800px, calc(100vw - 28px));
}

.help-body {
  padding: 25px 30px 28px;
}

.help-step {
  display: grid;
  grid-template-columns: 30px 86px 1fr;
  align-items: center;
  gap: 17px;
  padding: 15px 0;
  border-bottom: 1px solid rgba(97, 219, 222, 0.08);
}

.help-step:first-child {
  padding-top: 0;
}

.step-number {
  color: var(--cyan-soft);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 600;
}

.step-visual {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 55px;
  border: 1px solid rgba(84, 243, 255, 0.13);
  border-radius: 10px;
  background:
    radial-gradient(circle at 50% 50%, rgba(84, 243, 255, 0.065), transparent 70%),
    rgba(3, 13, 18, 0.48);
}

.help-step h3 {
  margin: 0 0 5px;
  color: #d6eeee;
  font-size: 13px;
  font-weight: 500;
}

.help-step p {
  margin: 0;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.55;
}

.drag-visual {
  gap: 7px;
}

.mini-port {
  width: 8px;
  height: 8px;
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 50%;
}

.mini-port.high {
  background: var(--amber);
  box-shadow: 0 0 8px rgba(255, 195, 95, 0.7);
}

.mini-port.low {
  background: var(--cyan);
  box-shadow: 0 0 8px rgba(84, 243, 255, 0.7);
}

.mini-wire {
  width: 32px;
  height: 1px;
  background: linear-gradient(90deg, var(--amber), var(--cyan));
  box-shadow: 0 0 7px rgba(84, 243, 255, 0.4);
}

.mini-switch {
  position: relative;
  width: 37px;
  height: 16px;
  border: 1px solid rgba(84, 243, 255, 0.25);
  border-radius: 3px;
}

.mini-switch::before,
.mini-switch::after {
  content: '';
  position: absolute;
  top: 5px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--cyan-soft);
}

.mini-switch::before { left: 4px; }
.mini-switch::after { right: 4px; }

.mini-switch i {
  position: absolute;
  left: 8px;
  top: 7px;
  width: 18px;
  height: 1px;
  background: var(--mint);
  transform: rotate(-20deg);
  transform-origin: left center;
  box-shadow: 0 0 5px var(--mint);
}

.led-visual span {
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 15px rgba(255, 195, 95, 0.8), 0 0 35px rgba(255, 195, 95, 0.3);
}

.manual-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
  margin-top: 21px;
}

.manual-grid > div {
  padding: 12px;
  border: 1px solid rgba(97, 219, 222, 0.09);
  border-radius: 9px;
  background: rgba(4, 15, 20, 0.4);
}

.manual-grid b {
  display: block;
  margin-bottom: 5px;
  color: var(--cyan-soft);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.1em;
}

.manual-grid p {
  margin: 0;
  color: var(--muted);
  font-size: 9.5px;
  line-height: 1.5;
}

.shortcut-row {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 20px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
}

.shortcut-row kbd {
  display: inline-block;
  min-width: 17px;
  margin-right: 3px;
  padding: 2px 4px;
  border: 1px solid rgba(133, 196, 200, 0.14);
  border-radius: 3px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 6.5px;
  text-align: center;
}

/* toast */

.toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 9px;
  max-width: calc(100vw - 28px);
  padding: 10px 16px;
  border: 1px solid rgba(84, 243, 255, 0.24);
  border-radius: 99px;
  background: rgba(6, 20, 26, 0.94);
  color: #cde9ea;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.03em;
  box-shadow: 0 14px 42px rgba(0, 0, 0, 0.48), 0 0 22px rgba(84, 243, 255, 0.06);
  transform: translate(-50%, 18px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease, transform 0.22s ease;
}

.toast.visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast.danger {
  border-color: rgba(255, 91, 110, 0.34);
}

.toast.danger .toast-icon {
  background: var(--danger);
  box-shadow: 0 0 9px rgba(255, 91, 110, 0.8);
}

.toast-icon {
  width: 6px;
  height: 6px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 9px rgba(84, 243, 255, 0.85);
}

/* ------------------------------------ responsive ------------------------------------ */

@media (max-width: 1240px) {
  .game-grid {
    grid-template-columns: minmax(210px, 240px) minmax(0, 1fr);
  }

  .control-panel {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: 0.9fr 1.1fr 1fr 1fr;
    align-items: stretch;
    min-height: 0;
  }

  .next-chip {
    margin-top: 0;
  }

  .score-card,
  .diagnostic-card,
  .legend-card {
    min-height: 0;
  }
}

@media (max-width: 980px) {
  .topbar {
    grid-template-columns: 1fr auto;
    gap: 13px;
  }

  .topbar-middle {
    grid-column: 1 / -1;
    grid-row: 2;
    padding-top: 2px;
  }

  .top-progress-track {
    width: auto;
    flex: 1;
  }

  .game-grid {
    grid-template-columns: 1fr;
    gap: 14px;
  }

  .board-column {
    grid-row: 1;
  }

  .mission-panel {
    grid-row: 2;
    min-height: 0;
  }

  .control-panel {
    grid-row: 3;
    grid-column: auto;
    grid-template-columns: repeat(3, 1fr);
  }

  .next-chip {
    display: none;
  }

  .engineer-note {
    margin-top: 22px;
  }
}

@media (max-width: 780px) {
  .app {
    padding: 10px 10px 12px;
  }

  .topbar {
    padding-bottom: 10px;
  }

  .brand-mark {
    width: 38px;
    height: 38px;
    border-radius: 11px;
  }

  .brand-title {
    font-size: 17px;
  }

  .brand-kicker {
    font-size: 7px;
  }

  .icon-button {
    width: 36px;
    height: 36px;
  }

  .level-button {
    min-height: 36px;
    padding: 0 9px;
  }

  .level-button span {
    display: none;
  }

  .level-button em {
    margin-left: 0;
  }

  .game-grid {
    padding: 12px 0;
  }

  .board-topline {
    min-height: 28px;
  }

  .interaction-hint span {
    display: none;
  }

  .interaction-hint svg {
    width: 17px;
    height: 17px;
  }

  .board-shell {
    padding: 8px;
    border-radius: 18px;
  }

  .canvas-wrap {
    border-radius: 12px;
  }

  .board-hud {
    top: 8px;
    padding: 5px 7px;
  }

  .hud-left { left: 8px; }
  .hud-right { right: 8px; }

